import sys, json, random, bisect
sys.path.insert(0,'/workspace/project')
import main as impl
import ref

TOKENS = ["GET", "POST", "PUT", "X", "HTTP/1.1", "/x", "/", "a b", "", "Host", "Host:",
          "h.example", "Content-Length: 0", "Content-Length: 3", "Content-Length: 3, 3",
          "Content-Length: 3, 4", "Content-Length: ", "Transfer-Encoding: chunked",
          "Transfer-Encoding: gzip", "X-T: v", "X-T:", ": v", "bad header", "\r\n",
          "5\r\nhello\r\n", "0\r\n\r\n", "zz\r\n", "1;x=y\r\n", "\r", "\n", "abc",
          "X-é: v\r\n", "X-ÿ: v\r\n", "é", "\u00ff", "ü\r\n"]

def gen(rng, n):
    out = []
    for _ in range(n):
        out.append(rng.choice(TOKENS))
        if rng.random() < 0.5:
            out.append("\r\n")
    return "".join(out)

def owner_fn(offsets):
    ends = [o[1] for o in offsets]
    def f(start, end):
        spans = []
        i = bisect.bisect_right(ends, start)
        for k in range(i, len(offsets)):
            lo, hi, own = offsets[k]
            if lo >= end: break
            a = max(lo, start); b = min(hi, end)
            if b > a: spans.append((own, b-a))
        order = []; counts = {}
        for lab, c in spans:
            if lab in counts: counts[lab] += c
            else: counts[lab] = c; order.append(lab)
        owner = spans[0][0] if spans else None
        return owner, [[l, counts[l]] for l in order]
    return f

def run(doc):
    try:
        return impl.run(doc)
    except Exception:
        return {'error':'input'}

def run_one(seed):
    rng = random.Random(seed)
    text = gen(rng, rng.randint(1, 14))
    data = text.encode('utf8')
    nparts = rng.randint(1, 3)
    cuts = sorted(rng.sample(range(0, len(data)+1), min(nparts, len(data)+1)))
    bounds = [0]+cuts+[len(data)]
    parts = []
    owners = ['a', None]
    for i in range(len(bounds)-1):
        chunk = text.encode('utf8')[bounds[i]:bounds[i+1]] if False else None
        parts.append((rng.choice(owners), bounds[i], bounds[i+1]))
    # use character-safe slicing: re-encode per part using byte offsets that are
    # guaranteed to be utf8 boundaries is complex, so split on characters instead
    parts = []
    chars = list(text)
    idxs = sorted(rng.sample(range(0, len(chars)+1), min(nparts, len(chars)+1)))
    prev = 0
    for i in idxs:
        parts.append((rng.choice(owners), "".join(chars[prev:i])))
        prev = i
    parts.append((rng.choice(owners), "".join(chars[prev:])))
    doc = {"seed":"s","definitions":[],"timeout_ms":10,
           "cases":[{"name":"a","frames":[{"Type":"headers","data_to_transfered":[[":method","GET"]],"End_Stream":True}],
                     "expect":{"method":"GET","target":"/x","host":"h.example"}}],
           "events":[],
           "channels":[{"name":"c","parts":[{"case":o,"data":p} for o,p in parts]}]}
    out = run(doc)
    if 'error' in out:
        return ('INPUT_ERROR', text, parts, None)
    ch = out['channels'][0]
    data = text.encode('utf8')
    offsets = []
    pos = 0
    for o,p in parts:
        b = p.encode('utf8')
        offsets.append((pos, pos+len(b), o)); pos += len(b)
    try:
        recs = ref.parse_all(data, owner_fn(offsets))
        err = None
    except ref.Syntax:
        recs = None; err = 'syntax'
    except ref.Incomplete:
        recs = None; err = 'incomplete'
    got = ch['requests']
    if recs is None:
        if ch['error'] is None or ch['error']['kind'] != err:
            return ('MISMATCH_ERR', text, parts, (ch['error'], err))
        return None
    if ch['error'] is not None:
        return ('MISMATCH_ERR2', text, parts, (ch['error'], err))
    if len(got) != len(recs):
        return ('MISMATCH_COUNT', text, parts, (len(got), len(recs)))
    for g, r in zip(got, recs):
        for key in ('start','end','method','target','host','host_count','headers','body','trailers','framing','owner','owners'):
            if g[key] != r[key]:
                return ('MISMATCH_FIELD:'+key, text, parts, (g[key], r[key]))
    if ch['bytes'] != ref.fp(data):
        return ('MISMATCH_BYTES', text, parts, (ch['bytes'], ref.fp(data)))
    return None

bad = 0
for seed in range(int(sys.argv[1]) if len(sys.argv)>1 else 500):
    r = run_one(seed)
    if r:
        bad += 1
        print('FAIL seed', seed, r[0])
        print('  text', repr(r[1])[:200])
        print('  detail', str(r[3])[:300])
        if bad > 4: break
print('done, failures:', bad)
